namespace Icinga\Module\Icingabridge\Controllers;

use Icinga\Module\Icingabridge\AccessUrlIniRepository;
use Icinga\Module\Icingabridge\Forms\AccessUrlForm;
use Icinga\Web\Controller;


class AccessurlController extends Controller
{
    /**
     * Set the title tab
     *
     * @param string $label
     */
    public function setTitle($label)
    {
        $this->getTabs()->add(uniqid(), [
            'active' => true,
            'label' => $label,
            'url' => $this->getRequest()->getUrl()
        ]);
    }


    public function init()
    {
        $this->assertPermission('icingabridge/accessurl/config');
    }

    public function indexAction()
    {
        $this->setTitle($this->translate('Access URLs'));
        $this->view->configs = (new AccessUrlIniRepository())->select();

        $this->_helper->viewRenderer->setRender('accessurl/table', null, true);
    }

    public function newAction()
    {
        $form = new AccessUrlForm([
            'mode' => AccessUrlForm::MODE_INSERT
        ]);
        $form->setDefaults(['local_url' => base64_decode($this->params->get('local_url'))]);
        $form->handleRequest();

        $this->setTitle($this->translate('New Access URL'));

        $this->view->form = $form;

        $this->_helper->viewRenderer->setRender('form', null, true);
    }

    public function updateAction()
    {
        $id = $this->params->getRequired('id');

        $form = new AccessUrlForm([
            'mode' => AccessUrlForm::MODE_UPDATE,
            'identifier' => $id
        ]);

        $form->handleRequest();


        $this->setTitle($this->translate('Update Access URL'));

        $this->view->form = $form;

        $this->_helper->viewRenderer->setRender('form', null, true);
    }

    public function deleteAction()
    {
        $id = $this->params->getRequired('id');

        $form = new AccessUrlForm([
            'mode' => AccessUrlForm::MODE_DELETE,
            'identifier' => $id
        ]);

        $form->handleRequest();

        $this->setTitle($this->translate('Remove Access URL'));

        $this->view->form = $form;

        $this->_helper->viewRenderer->setRender('form', null, true);
    }
}
